import{_ as t}from"./chunks/06.BRtrInto.js";import{_ as a,o as e,c as r,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/academy/img/okno-spp/04.webp",l="/buildary-help-preview/academy/img/schvalovani-spp/07.webp",g=JSON.parse('{"title":"Zadat a schválit soupis","description":"","frontmatter":{"title":"Zadat a schválit soupis","wiki":"cs:performedworks:contractor_actions"},"headers":[],"relativePath":"performedworks/contractor_actions.md","filePath":"performedworks/contractor_actions.md","lastUpdated":1794209661000}'),d={name:"performedworks/contractor_actions.md"};function v(p,o,i,h,u,k){return e(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="zadat-a-schvalit-soupis" tabindex="-1">Zadat a schválit soupis <a class="header-anchor" href="#zadat-a-schvalit-soupis" aria-label="Permalink to &quot;Zadat a schválit soupis&quot;">​</a></h1><p>Zhotovitel zadá provedené množství a odešle zjišťovací protokol na schválení. Stavebník posoudí každou položku a protokol schválí, nebo ho vrátí k opravě. Mezi zhotovitelem a podzhotovitelem probíhá soupis stejně, jen v jiných rolích.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/schvalovani-spp">Odeslat a schválit soupis prací</a> v Akademii.</p><h2 id="kdo-co-dela" tabindex="-1">Kdo co dělá <a class="header-anchor" href="#kdo-co-dela" aria-label="Permalink to &quot;Kdo co dělá&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Krok</th><th>SPP Zhotovitele</th><th>SPP Podzhotovitele</th></tr></thead><tbody><tr><td>Zadá množství a odešle protokol na schválení</td><td>zástupce zhotovitele</td><td>zástupce podzhotovitele</td></tr><tr><td>Posoudí položky, schválí protokol nebo ho vrátí k opravě</td><td>zástupce stavebníka</td><td>zástupce zhotovitele</td></tr><tr><td>Opraví vrácené položky a odešle protokol znovu</td><td>zástupce zhotovitele</td><td>zástupce podzhotovitele</td></tr></tbody></table><p>Kdo smí zadávat a kdo schvalovat, určují kompetence v projektovém týmu – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>. V dalším textu píšeme o zhotoviteli a stavebníkovi. V SPP Podzhotovitele platí totéž pro podzhotovitele a zhotovitele.</p><h2 id="stavy-zjistovaciho-protokolu" tabindex="-1">Stavy zjišťovacího protokolu <a class="header-anchor" href="#stavy-zjistovaciho-protokolu" aria-label="Permalink to &quot;Stavy zjišťovacího protokolu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stav</th><th>Co se děje</th><th>Tlačítka v záhlaví</th></tr></thead><tbody><tr><td><strong>Návrh</strong></td><td>Zhotovitel zadává množství.</td><td><strong>Odeslat na schválení</strong></td></tr><tr><td><strong>Schvalování</strong></td><td>Stavebník posuzuje položky. Zhotovitel vidí stavy položek a fakturované hodnoty, ale nemůže je měnit.</td><td><strong>Vrátit k opravě</strong>, <strong>Schválit</strong></td></tr><tr><td><strong>Změna návrhu</strong></td><td>Stavebník protokol vrátil, zhotovitel opravuje položky ve stavu <strong>V jednání</strong>.</td><td><strong>Odeslat na schválení</strong></td></tr><tr><td><strong>Uzavřeno</strong></td><td>Stavebník protokol schválil a tím uzamkl. Protokol slouží jako podklad k fakturaci, ve výstupech je období označené jako <strong>Schváleno</strong> – viz <a href="/buildary-help-preview/performedworks/output_methods#podklad-k-fakturaci">Výstupy soupisů</a>.</td><td><strong>Odemknout</strong></td></tr></tbody></table><p>Stav protokolu vidíte v záhlaví sloupců vybraného období, například <strong>Říjen 2026 – Schvalování</strong>. O změnách stavu protokolu dostávají účastníci e-mail, pokud mají zapnutá e-mailová oznámení – viz <a href="/buildary-help-preview/performedworks/competences#e-mailova-oznameni">Kompetence pro soupisy</a>.</p><h2 id="stavy-polozky" tabindex="-1">Stavy položky <a class="header-anchor" href="#stavy-polozky" aria-label="Permalink to &quot;Stavy položky&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stav</th><th>Význam</th><th>Vyřešená</th></tr></thead><tbody><tr><td><strong>Návrh</strong></td><td>Zhotovitel položku navrhl, stavebník ji zatím neposoudil.</td><td>ne</td></tr><tr><td><strong>V jednání</strong></td><td>Stavebník položku zatím neuzavřel a čeká na opravu od zhotovitele.</td><td>ne</td></tr><tr><td><strong>Schváleno</strong></td><td>Stavebník navržené množství schválil.</td><td>ano</td></tr><tr><td><strong>Změna</strong></td><td>Stavebník schválil jiné množství, než zhotovitel navrhl.</td><td>ano</td></tr><tr><td><strong>Zamítnuto</strong></td><td>Stavebník čerpání položky zamítl. Fakturované množství a cena jsou nulové.</td><td>ano</td></tr></tbody></table><p>Protokol lze schválit, až když jsou vyřešené všechny položky.</p><h2 id="zadat-soupis" tabindex="-1">Zadat soupis <a class="header-anchor" href="#zadat-soupis" aria-label="Permalink to &quot;Zadat soupis&quot;">​</a></h2><p>Zhotovitel zadává množství ve sloupcích <strong>Navržené množství</strong> nebo <strong>Navržená cena</strong>, když je protokol ve stavu <strong>Návrh</strong> nebo když za období ještě neexistuje. Množství můžete zadat i v procentech nebo hromadně – viz <a href="/buildary-help-preview/performedworks/application_window#zadat-mnozstvi">Okno soupisu</a>.</p><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Sloupec Navržené množství s vyplněnými množstvími a aktivním tlačítkem Odeslat na schválení" loading="lazy"></figure><p>Čerpání lze také načíst ze souboru XML ve formátu XC4 nebo ze souboru JSON.</p><p>Když je návrh za období hotový, klikněte na <strong>Odeslat na schválení</strong>. Protokol přejde do stavu <strong>Schvalování</strong>.</p><h2 id="schvalit-soupis" tabindex="-1">Schválit soupis <a class="header-anchor" href="#schvalit-soupis" aria-label="Permalink to &quot;Schválit soupis&quot;">​</a></h2><p>Po odeslání vidí stavebník sloupce <strong>Fakturované množství</strong>, <strong>Stav položky</strong> a <strong>Fakturovaná cena</strong>. Všechny položky jsou ve stavu <strong>Návrh</strong> a fakturované množství odpovídá navrženému.</p><figure class="shot" style="--w:760px;"><img src="'+t+'" alt="Protokol ve stavu Schvalování s položkami ve stavu Schváleno a tlačítky Vrátit k opravě a Schválit" loading="lazy"></figure><h3 id="posoudit-polozky" tabindex="-1">Posoudit položky <a class="header-anchor" href="#posoudit-polozky" aria-label="Permalink to &quot;Posoudit položky&quot;">​</a></h3><p>Stav položky změníte:</p><ul><li>výběrem ve sloupci <strong>Stav položky</strong>,</li><li>klávesovou zkratkou (tabulka níže),</li><li>hromadně u označených položek – viz <a href="/buildary-help-preview/performedworks/application_window#hromadne-operace">Okno soupisu</a>.</li></ul><table tabindex="0"><thead><tr><th>Stav</th><th>Klávesová zkratka</th></tr></thead><tbody><tr><td><strong>Schváleno</strong></td><td>Alt + S</td></tr><tr><td><strong>Zamítnuto</strong></td><td>Alt + X</td></tr><tr><td><strong>V jednání</strong></td><td>Alt + V</td></tr><tr><td><strong>Změna</strong></td><td>Alt + Z</td></tr><tr><td><strong>Návrh</strong></td><td>Alt + N</td></tr></tbody></table><p>Zkratky platí pro českou a slovenskou verzi aplikace.</p><p>Stav položky se mění také podle fakturovaných hodnot:</p><ul><li>Když změníte <strong>Fakturované množství</strong> nebo <strong>Fakturovanou cenu</strong>, položka přejde do stavu <strong>Změna</strong> – je schválená se změnou.</li><li>Když fakturované množství nebo cenu vynulujete, položka přejde do stavu <strong>Zamítnuto</strong>. Naopak stav <strong>Zamítnuto</strong> fakturované množství i cenu vynuluje.</li></ul><p>K položce můžete napsat poznámku, například proč ji vracíte – viz <a href="/buildary-help-preview/performedworks/application_window#poznamky-k-polozkam">Okno soupisu</a>.</p><h3 id="schvalit-protokol" tabindex="-1">Schválit protokol <a class="header-anchor" href="#schvalit-protokol" aria-label="Permalink to &quot;Schválit protokol&quot;">​</a></h3><p>Když jsou všechny položky vyřešené, klikněte na <strong>Schválit</strong>. Protokol přejde do stavu <strong>Uzavřeno</strong>. Dokud některá položka zůstává ve stavu <strong>Návrh</strong> nebo <strong>V jednání</strong>, protokol schválit nelze.</p><p>Schválený protokol je uzamčený. Zhotovitel dostane e-mail s elektronicky podepsaným zjišťovacím protokolem v PDF – viz <a href="/buildary-help-preview/performedworks/output_methods">Výstupy soupisů</a>.</p><h3 id="vratit-k-oprave" tabindex="-1">Vrátit k opravě <a class="header-anchor" href="#vratit-k-oprave" aria-label="Permalink to &quot;Vrátit k opravě&quot;">​</a></h3><p>Když chcete, aby zhotovitel některé položky opravil, nastavte jim stav <strong>V jednání</strong> a klikněte na <strong>Vrátit k opravě</strong>. Protokol přejde do stavu <strong>Změna návrhu</strong>. Položky, které zůstaly ve stavu <strong>Návrh</strong>, přejdou do stavu <strong>V jednání</strong>.</p><h2 id="opravit-vraceny-soupis" tabindex="-1">Opravit vrácený soupis <a class="header-anchor" href="#opravit-vraceny-soupis" aria-label="Permalink to &quot;Opravit vrácený soupis&quot;">​</a></h2><p>Ve stavu <strong>Změna návrhu</strong> zhotovitel zadává nové množství ve sloupci <strong>Změna návrhu</strong>. Upravit může jen:</p><ul><li>položky ve stavu <strong>V jednání</strong>,</li><li>položky, které zatím nemají žádné navržené množství.</li></ul><p>Položky, které stavebník už vyřešil, upravit nemůžete. Po opravě klikněte znovu na <strong>Odeslat na schválení</strong>. Stavebník pak posoudí opravené položky stejně jako poprvé.</p><h2 id="odemknout-schvaleny-protokol" tabindex="-1">Odemknout schválený protokol <a class="header-anchor" href="#odemknout-schvaleny-protokol" aria-label="Permalink to &quot;Odemknout schválený protokol&quot;">​</a></h2><p>Schválený protokol lze odemknout tlačítkem <strong>Odemknout</strong> a pak upravit. Kdo to smí, popisuje <a href="/buildary-help-preview/performedworks/competences#kompetence-roli">Kompetence pro soupisy</a>.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Schválený zjišťovací protokol s oranžovým tlačítkem Odemknout" loading="lazy"></figure>',40)])])}const z=a(d,[["render",v]]);export{g as __pageData,z as default};
